// Route types are generated by Next.js (`typedRoutes: true`) into `.next/types/routes.d.ts`
// on `next dev`, `next build`, or `next typegen`.
import type { ParamMap } from "../../../.next/types/routes";

/** Every route pattern known to Next.js, e.g. `/dashboard/finance` or `/blog/[slug]`. */
export type RoutePattern = keyof ParamMap;

/** Params required to build the given route pattern. `{}` for static routes. */
export type RouteParams<R extends RoutePattern> = ParamMap[R];

/** Route patterns with no dynamic segments. */
export type StaticRoutePattern = {
  [R in RoutePattern]: keyof RouteParams<R> extends never ? R : never;
}[RoutePattern];

/** Route patterns with at least one dynamic segment. */
export type DynamicRoutePattern = Exclude<RoutePattern, StaticRoutePattern>;

export type RouteQueryValue = string | number | boolean | null | undefined;

export interface RouteOptions {
  /** Appended as `?key=value`. `null`/`undefined` values are skipped; arrays repeat the key. */
  query?: Record<string, RouteQueryValue | readonly RouteQueryValue[]>;
  /** Appended as `#hash` (without the leading `#`). */
  hash?: string;
}

/** Static routes take only options; dynamic routes require their params first. */
export type RouteArgs<R extends RoutePattern> = keyof RouteParams<R> extends never
  ? [options?: RouteOptions]
  : [params: RouteParams<R>, options?: RouteOptions];
